// Each module's source, dependencies first, relative imports rewritten to
// 'claudinite-locator:<module>' until loadLocators links them.
const SOURCES = {
  "engine/checks/helpers/chrome-manifest.mjs": "// Shared engine helper: the first tracked Chrome-extension manifest\n// (a manifest.json declaring manifest_version) \u2014 a structural primitive the\n// extension technology packs build their checks and fingerprint on.\nexport function findExtensionManifest(ctx) {\n  return ctx.tracked.find((f) => {\n    if (!f.endsWith('manifest.json')) return false;\n    const text = ctx.read(f);\n    return text !== null && /\"manifest_version\"/.test(text);\n  }) ?? null;\n}\n",
  "packs/android/pack.mjs": "// Technology stub pack: Android app development (Gradle/AGP, manifests, permissions, signing, flavors).\n// No rules captured yet, so no RULES.md.\nexport default {\n  version: '60925.1',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'gradle/AGP builds, AndroidManifest, permissions, signing configs, product flavors and emulator workflows for an Android app module',\n    excludes: 'store submission and release cadence \u2014 play-store-release; Flutter-side widget or Dart code \u2014 flutter',\n  },\n  pitch: 'This pack starts empty. It is the place where an Android repo\\'s own hard-won lessons accumulate as its Claude Code sessions run into them: Gradle and build quirks, manifest permissions, signing and release builds, emulator and device testing. Nothing ships in it yet, so adopting it today adds no rules or checks; what it adds is a home, so the next time a session learns something the painful way about Android, that lesson is captured and every later session starts out knowing it.',\n  marker: 'android/app/src/main/AndroidManifest.xml',\n  detect: (ctx) => ctx.tracked.some((f) => f.endsWith('android/app/src/main/AndroidManifest.xml')),\n};\n",
  "packs/aws-sam/pack.mjs": "\n// The AWS Serverless Application Model and the API-Gateway/CloudFront stack it\n// deploys: the gotchas any SAM project hits, as checks, prose and two skills.\nexport default {\n  version: '60927.1',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'serverless AWS stacks: SAM template shape, Lambda handler paths, esbuild bundling, API Gateway and CloudFront gotchas',\n    excludes: 'backend Google ID token validation \u2014 google-identity; generic Node packaging habits \u2014 node',\n  },\n  pitch: 'Keeps Claude Code sessions from breaking a SAM deployment in the ways that cost an afternoon. A few rules cover change sets that would replace a live resource, a failed first stack creation that has to be cleaned up, CloudFront verification on a new account and CORS preflights. Two skills, for shaping the template and one for build dependencies, load before any template or package edit, and a handful of blocking checks catch a wrong handler path, a missing esbuild dependency and CloudFront authorization mistakes before they reach AWS.',\n  marker: 'a SAM template (template.yaml/.yml)',\n  detect: (ctx) => ctx.tracked.includes('template.yaml') || ctx.tracked.includes('template.yml'),\n};\n",
  "packs/chrome-extension/pack.mjs": "import { findExtensionManifest } from 'claudinite-locator:engine/checks/helpers/chrome-manifest.mjs';\n\n// Everything about a Chrome extension in one pack: the MV3 build/runtime gotchas\n// that apply while you are writing one, and the Chrome-Web-Store release standard\n// that applies once you publish it. Fingerprinted by the manifest, which is what a\n// repo has from its first commit.\n//\n// THE RELEASE HALF IS GATED ON SHIPPING, not on a second declaration (#1057). It\n// used to be its own opt-in pack, chrome-extension-release, whose `detect` was the\n// orchestrator workflow's name \u2014 so the fact that decided whether the release rules\n// applied was always structural, and the declaration was a second copy of it that a\n// repo had to remember to write. Now that fact is read where it is used:\n// `shipsReleasePipeline` gates the coded rule, and every declared check carries the\n// same test as its `relevantWhen`. A repo that only codes an extension sees none of\n// them; a repo that publishes gets them without anyone declaring anything.\n//\n// The `cer/` check ids are kept as they are. A member's `accept` entries name rules\n// by id, and renaming one silently orphans an acceptance \u2014 the finding comes back\n// with nothing to carry the member across. A prefix outliving the pack it was named\n// for is the cheaper of those two.\n// The release standard itself \u2014 the pipeline's contract, the setup for a new\n// extension repo, and the store steps no automation can take \u2014 is skills/, not\n// prose: it is long, and only the checks need to be eager.\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'writing and shipping a Chrome extension: MV3 service-worker, permission, content-script and auth gotchas, plus Web Store release, versioning and privacy',\n    excludes: 'generic workflow lint rules \u2014 git-github; shipping to a different store \u2014 the app-store-release and play-store-release packs',\n  },\n  pitch: 'For a repo that builds a Manifest V3 extension, this carries the gotchas that otherwise surface as silent failures: service worker paths, re-injected content scripts, host permissions, sign-in tokens and extension UI surfaces. About twenty rules and some twenty checks catch them while code is being written. Two skills cover host permissions and the Chrome Web Store release standard, and once the repo ships the release pipeline, a daily task builds and publishes the store release by itself, with conformance checks keeping the pipeline intact.',\n  marker: 'a manifest.json declaring manifest_version',\n  detect: (ctx) => findExtensionManifest(ctx) !== null,\n  // Delivery, not state: the tree always carries a version, and only the diff\n  // says whether it moved with the shipped files beside it.\n  // Pack-contributed task: `tasks/store-release/` \u2014 the scheduler's filesystem scan\n  // (packs/claudinite-tasks/discover.mjs) picks it up on any repo declaring this pack, so\n  // its own precondition is what keeps it off a repo that does not publish.\n};\n",
  "packs/cloudflare-site/lib.mjs": "// What the repo's own wrangler config says about the deployment: which tree is\n// published, and which hostnames the Worker claims. Every other file in this pack\n// asks these two questions, and none of them asks the repo to repeat the answers\n// as config \u2014 the config file wrangler already reads is the one source.\n//\n// JSON only (`wrangler.json`/`wrangler.jsonc`). A TOML config is a legitimate\n// wrangler setup and simply not one this pack reads: parsing a second\n// configuration language to answer two questions buys nothing that moving the\n// config does not, and `publishes-a-site-directory` says so where a repo meets it.\n\n// The config filenames wrangler resolves, in its own precedence order.\nexport const WRANGLER_CONFIGS = ['wrangler.json', 'wrangler.jsonc'];\n\n// The config in `paths`, at the repo root or one directory down \u2014 the same reach\n// the cloudflare-workers pack fingerprints on, so a stray config in a fixture or\n// example tree deeper in the tree is not mistaken for the deployment's.\nexport function wranglerConfigPath(paths = []) {\n  const candidates = paths.filter((p) => {\n    const parts = p.split('/');\n    return parts.length <= 2 && WRANGLER_CONFIGS.includes(parts[parts.length - 1]);\n  });\n  // Shallowest first, then the extension order wrangler itself prefers.\n  candidates.sort((a, b) => a.split('/').length - b.split('/').length\n    || WRANGLER_CONFIGS.indexOf(a.split('/').pop()) - WRANGLER_CONFIGS.indexOf(b.split('/').pop()));\n  return candidates[0] ?? null;\n}\n\n// JSONC to JSON: drop `//` and `/* */` comments that are not inside a string.\n// Hand-written because the whole need is two comment forms over a file wrangler\n// itself accepts, and a dependency for that is a dependency to keep.\nexport function stripJsonComments(text) {\n  let out = '';\n  let inString = false;\n  let inLine = false;\n  let inBlock = false;\n  for (let i = 0; i < text.length; i += 1) {\n    const c = text[i];\n    const next = text[i + 1];\n    if (inLine) { if (c === '\\n') { inLine = false; out += c; } continue; }\n    if (inBlock) { if (c === '*' && next === '/') { inBlock = false; i += 1; } continue; }\n    if (inString) {\n      out += c;\n      if (c === '\\\\') { out += next ?? ''; i += 1; } else if (c === '\"') inString = false;\n      continue;\n    }\n    if (c === '\"') { inString = true; out += c; continue; }\n    if (c === '/' && next === '/') { inLine = true; i += 1; continue; }\n    if (c === '/' && next === '*') { inBlock = true; i += 1; continue; }\n    out += c;\n  }\n  return out;\n}\n\n// The parsed config, or null when it is absent or unparseable \u2014 the callers all\n// have something to say about that themselves.\nexport function parseWranglerConfig(text) {\n  if (typeof text !== 'string') return null;\n  try { return JSON.parse(stripJsonComments(text)); } catch { return null; }\n}\n\n// The published tree, as a repo-relative path: `assets.directory` resolved against\n// the directory holding the config, exactly as wrangler resolves it.\nexport function publishedDir(config, configPath = 'wrangler.json') {\n  const dir = config?.assets?.directory;\n  if (typeof dir !== 'string' || !dir.trim()) return null;\n  const base = configPath.includes('/') ? `${configPath.slice(0, configPath.lastIndexOf('/'))}/` : '';\n  const normalized = dir.replace(/^\\.\\//, '').replace(/\\/+$/, '');\n  return `${base}${normalized}`;\n}\n\n// The hostnames the deploy attaches as custom domains \u2014 the ones a visitor types,\n// and the ones a record inherited from a previous host can block or shadow.\nexport function claimedHostnames(config) {\n  const routes = Array.isArray(config?.routes) ? config.routes : [];\n  return routes\n    .filter((r) => r && r.custom_domain === true && typeof r.pattern === 'string')\n    .map((r) => r.pattern);\n}\n\n// The Cloudflare Web Analytics beacon token is public \u2014 it ships in the client \u2014 so it\n// rides a repository VARIABLE and is substituted into the copy being uploaded, never\n// into the commit. A loader carrying this placeholder no-ops while it is still in\n// place. Here rather than in the release worker because the check that keeps a real\n// token out of the tree names it too, and a check may not drag a task's worker (and\n// its imports) into every sweep.\nexport const BEACON_PLACEHOLDER = 'REPLACE_WITH_CLOUDFLARE_WEB_ANALYTICS_TOKEN';\n",
  "packs/cloudflare-site/pack.mjs": "// Technology-plus-aspect pack: a static tree served from Cloudflare Workers static\n// assets on its own domain, the nightly release that uploads it, the boundary of what\n// reaches a public URL, and the parts of the deployment only a person holding the\n// Cloudflare account can do. The version is not here: public-website owns the scheme\n// and the page stamp, and the release reaches that pack's `public/version.mjs` to\n// advance it when the pack is declared.\nimport { parseWranglerConfig, wranglerConfigPath } from 'claudinite-locator:packs/cloudflare-site/lib.mjs';\n\nconst servesASite = (ctx) => {\n  const path = wranglerConfigPath(ctx.tracked);\n  return Boolean(path && parseWranglerConfig(ctx.read(path))?.assets?.directory);\n};\n\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'serving a static site from Cloudflare: the published tree, custom domains, the nightly release that uploads it',\n    excludes: 'Workers runtime and bindings \u2014 cloudflare-workers; the version scheme and the page stamp \u2014 public-website; markup \u2014 html',\n  },\n  pitch: 'Gives a site served from Cloudflare exactly one path to production. A nightly release task advances the version, uploads the published tree, and reports what the domain answered and whether it is serving that version, parking with a named reason when a person has to act. A skill covers releasing, forcing a release and rolling one back. A few rules and checks keep stray files out of the upload, links free of needless redirects, and any second publisher from quietly shipping around the release.',\n  marker: 'a near-root wrangler.json/.jsonc declaring assets.directory',\n  detect: servesASite,\n  // The release is a work item: the queue owns its trigger, its gate, its secrets\n  // and its park lanes, which is the whole reason it is a task rather than a\n  // workflow.\n  requires: ['claudinite-tasks'],\n\n  // No interview. Everything this pack needs about a deployment \u2014 the published\n  // tree, the hostnames claimed, whether analytics is wanted \u2014 is already stated\n  // structurally in the repo (the wrangler config, and whether a published file\n  // carries the beacon placeholder), and a question whose answer is already in the\n  // tree is a second place for it to be wrong.\n\n  // What adoption genuinely cannot do: everything on the Cloudflare account. The\n  // zone's two DNS deletions are NOT here \u2014 they are leftovers a repo may or may\n  // not have, evaluated by the release's own preflight and by\n  // `no-second-publisher`, because a checkbox that is a no-op for most adopters\n  // teaches the reader to skim the list that exists to stop them skimming.\n  adoptionHandover: [\n    {\n      step: 'Add the site\\'s domain as a zone on the Cloudflare account, and point the registrar\\'s nameservers at the two Cloudflare shows at the end of that flow \u2014 https://dash.cloudflare.com/?to=/:account/add-site',\n      breaks: 'the deploy fails outright \u2014 the wrangler config claims the domain as a custom domain, so every release parks at needs-human-action until the zone reads Active',\n      done: 'the zone reads Active on https://dash.cloudflare.com/?to=/:account/websites',\n    },\n    {\n      step: 'Add the Cloudflare Account ID (Overview, right-hand column) as the repository secret CLOUDFLARE_ACCOUNT_ID',\n      breaks: 'the release stops at its own gate, before it touches Cloudflare, parking with the missing secret named \u2014 nothing is left half-done',\n      done: 'a site-release run gets as far as wrangler',\n    },\n    {\n      step: 'Create an API token from the \"Edit Cloudflare Workers\" template (https://dash.cloudflare.com/profile/api-tokens) and add it as the repository secret CLOUDFLARE_API_TOKEN',\n      breaks: 'same gate as the account id; a token narrower than that template instead fails inside wrangler with a 10000-class error, which the worker parks as needs-human-action',\n      done: 'a site-release run uploads and the domain serves the site',\n    },\n  ],\n};\n",
  "packs/cloudflare-workers/pack.mjs": "// Technology pack: a backend built on the Cloudflare Workers runtime and its\n// bindings (D1, R2, Vectorize, Workflows, Workers AI, Containers) driven\n// through Wrangler. The platform's own limits and deploy-window hazards, and\n// the binding boundary that forces everything else into plain, fake-tested\n// modules.\nconst MARKERS = ['wrangler.toml', 'wrangler.json', 'wrangler.jsonc'];\nconst hasMarkerNearRoot = (ctx) =>\n  ctx.tracked.some((f) => {\n    const parts = f.split('/');\n    return MARKERS.includes(parts[parts.length - 1]) && parts.length <= 2;\n  });\n\nexport default {\n  version: '60925.1',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'the Cloudflare Workers platform: Wrangler, D1, R2, Vectorize, Workflows, Workers AI and Containers',\n    excludes: 'serving a static site from Workers assets \u2014 cloudflare-site; a different serverless vendor \u2014 aws-sam; generic Node conventions \u2014 node',\n  },\n  pitch: 'For a repo running Cloudflare Workers, about a dozen rules carry the platform lessons that are expensive to learn in production: routing large uploads through R2, sizing and keying Workflow steps, when native code needs a Container, why database migrations take three merges, telling absent data from unknown, and why a preview deploy URL is not production. The pack is rules only, with no skills, checks or tasks, and its guidance is kept reconciled against Cloudflare\\'s own documentation.',\n  marker: 'a wrangler.toml/.json/.jsonc config (at the repo root or one directory down)',\n  detect: hasMarkerNearRoot,\n};\n",
  "packs/executable-requirements/pack.mjs": "\n// The executable-requirements framework standard: the concrete, portable\n// conventions - layout, naming, gates, kinds, gallery, determinism - shared by\n// every project that runs its spec as tests.\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'running a numbered spec as tests: dev/requirements layout, requirement ids, kinds, coverage and gallery gates, determinism rules',\n    excludes: 'doc-first judgment, owner-owned expecteds and honest-gap tracking \u2014 spec-driven-product; general test practice \u2014 basics writing-tests',\n  },\n  pitch: 'Turns the repo\\'s requirements document into a spec that runs as tests. Every requirement line gets a case in a standard layout, and the project\\'s own gates prove each one is covered and that rendered outputs stay byte-stable. Three skills do the authoring work: writing a requirement leaf and picking its case kind, writing a saga that captures a multi-step story as a golden storyboard, and making rendered expected outputs deterministic. A couple of rules and a check keep the case layout consistent.',\n  marker: 'dev/requirements/requirements.md',\n  detect: (ctx) => ctx.tracked.includes('dev/requirements/requirements.md'),\n  questions: [\n    {\n      id: 'ui_testing',\n      prompt: 'How are the executable UI requirements exercised \u2014 what is the UI-testing mechanism (browser/E2E such as Playwright, DOM-level golden rendering, a headless harness), or is there none yet? Most requirements should be verifiable by a short test that drives to a state and makes a VISUAL assertion (a committed golden the owner checks by sight), so this fixes how a requirement becomes that assertion.',\n      distill: 'recorded as intent; it fixes the harness the requirements.md drives its UI gates through, and the visual-golden path most leaves take for simplest owner verification',\n    },\n    {\n      id: 'requirements_source',\n      prompt: 'Where do the requirements come from \u2014 an existing requirements/spec document, the issue tracker, or authored fresh? Name the path or source so the spec is seeded from it rather than reinvented.',\n      distill: \"record the source; set config.spec to the executable spec's home (default dev/requirements/requirements.md) and extract the initial requirements from the named source\",\n    },\n  ],\n};\n",
  "packs/firebase/pack.mjs": "// Technology pack: building on Firebase (Auth, Firestore, Cloud Functions,\n// FCM) \u2014 schema/rules discipline, function patterns, testing without live\n// infrastructure, and deploy layout. Fingerprint: firebase.json at the repo\n// root or one directory down, never deeper.\n\nconst hasMarkerNearRoot = (ctx, marker) =>\n  ctx.tracked.some((f) => {\n    const parts = f.split('/');\n    return parts[parts.length - 1] === marker && parts.length <= 2;\n  });\n\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'building on Firebase: Firestore rules, callable Cloud Function patterns, FCM, emulator testing, deploy layout, dev/prod release split',\n    excludes: 'app store submission and its store-side registration \u2014 play-store-release, app-store-release',\n  },\n  pitch: 'Firebase projects fail quietly when security rules allow more than intended or a Cloud Function trusts the wrong identity. This pack keeps Claude Code sessions on safe ground: a few always-on rules about admin-SDK bypass, verified-token identity and default-deny, plus skills for writing Firestore security rules, building Cloud Functions with transactional rate limits and batched fan-out, and planning a first release with separate dev and prod projects. A few checks hold the deploy layout, so predeploy build hooks and committed project aliases stay in place.',\n  marker: 'firebase.json (at the repo root or one directory down)',\n  detect: (ctx) => hasMarkerNearRoot(ctx, 'firebase.json'),\n  // The deploy-layout guards live beside this manifest: functions-predeploy-build\n  // in worldRules/, functions-node-pin in declared-checks.json. Both are\n  // relevance-first - see README.md.\n};\n",
  "packs/flutter/pack.mjs": "// Flutter and Dart practice: prose, two forbidden-pattern checks over the shipped\n// Dart tree, two path-forced skills, and the Flutter SDK a cloud session needs.\n// Fingerprint: a pubspec.yaml at the repo root or one directory down, never deeper.\nconst hasMarkerNearRoot = (ctx, marker) =>\n  ctx.tracked.some((f) => {\n    const parts = f.split('/');\n    return parts[parts.length - 1] === marker && parts.length <= 2;\n  });\n\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'widget-tree architecture, ports and fakes, widget-test and golden mechanics, pub and analyze toolchain habits for Flutter',\n    excludes: 'native Android or iOS module concerns \u2014 android and ios; store shipping \u2014 play-store-release, app-store-release',\n  },\n  pitch: 'Flutter code drifts toward widgets that call plugins directly and golden tests that hang or render boxes. This pack gives Claude Code sessions about a dozen rules for keeping plugins behind ports, making anything that fetches injectable, guarding async lifecycles, and keeping flutter analyze at zero issues. Its skills cover widget and golden test mechanics and telling a real dependency change from pubspec lockfile churn, while a few checks catch network fetches inside the widget tree before they reach review.',\n  marker: 'pubspec.yaml (at the repo root or one directory down)',\n  detect: (ctx) => hasMarkerNearRoot(ctx, 'pubspec.yaml'),\n  // The Flutter SDK isn't in the Claude Code Web base image, so a cloud session\n  // can't run `flutter test` / analyze / golden regen without it. This declares\n  // how the environment installs it (aggregated into environment-setup-command.sh) and\n  // how the SessionStart check asserts it \u2014 see engine/pack_loader/env-requirements.mjs.\n  env: {\n    label: 'Flutter SDK',\n    setup: [\n      'if [ ! -x /opt/flutter/bin/flutter ]; then',\n      '  git clone --depth 1 -b stable https://github.com/flutter/flutter.git /opt/flutter',\n      'fi',\n      'ln -sf /opt/flutter/bin/flutter /usr/local/bin/flutter',\n      'ln -sf /opt/flutter/bin/dart /usr/local/bin/dart',\n      'git config --global --add safe.directory /opt/flutter || true',\n      'flutter --version || true',\n      'flutter precache || true   # warm host engine artifacts so the first test is fast',\n    ].join('\\n'),\n    probe: 'command -v flutter >/dev/null 2>&1',\n  },\n};\n",
  "packs/github-pages/lib.mjs": "// What a repo says about its Pages deployment \u2014 `.github/site.config`, the one file\n// the deploy workflow's build step, the release task and the checks all read \u2014 and\n// the names of the vendored pieces. Every other file in this pack asks these\n// questions here, and none asks the repo to repeat the answers anywhere else.\n//\n// REQUIRED AND FULLY EXPLICIT \u2014 three keys, no defaults. A default that \"happens to\n// match\" a repo's layout silently publishes the wrong tree the day the layout or the\n// default changes, and the published set is exactly the thing that must never be\n// guessed:\n//\n//   publish_root    the directory the published site is rooted at (\".\" = the repo\n//                   root). Every publish path is relative to it, and it is what\n//                   becomes the site's \"/\".\n//   publish_paths   the explicit publish set \u2014 the files and directories under\n//                   publish_root that are copied into the artifact, and nothing\n//                   else. Space-separated, relative to publish_root.\n//   build_command   the command that produces whatever publish_paths names\n//                   (\"\" = nothing to build, stated).\n//\n// The set is ADDITIVE on purpose. The rejected alternative \u2014 \"publish the repo except\n// the tooling\" \u2014 publishes every draft, note and key nobody thought to exclude, and\n// publishes each new one silently the day it lands. An additive list can only ever\n// publish what the repo asked for, and its failure mode, a file that does not show\n// up, is visible on the site and caught by `gp/site-config` before it merges.\n//\n// A missing file, a missing key, an unknown (typo'd) key and an empty required path\n// key are all hard failures \u2014 a deploy that \"worked\" because a typo fell back to a\n// default is the failure mode this shape exists to prevent.\n//\n// One key is OPTIONAL, and deliberately so:\n//\n//   build_vars      space-separated names of repo VARIABLES the build may read,\n//                   exported into build_command's environment (absent = none).\n//\n// It is optional because the explicitness rule above exists to stop a default from\n// silently publishing the WRONG TREE \u2014 and an absent build_vars cannot do that.\n// Absent means the build sees no variables, which is what every site did before the\n// key existed. What is NOT tolerated is a declared name with no value behind it:\n// that is the silently half-configured build \u2014 a blank analytics token, an empty\n// base URL \u2014 baked into a published page, so a declared-but-unset variable fails\n// the run.\n//\n// VARIABLES, NEVER SECRETS. The build step is handed `toJSON(vars)`, a context that\n// structurally cannot carry a secret. A value that must not appear in a published\n// artifact has no business reaching the step whose output IS that artifact, so the\n// boundary is enforced by which context the workflow passes, not by a convention\n// someone has to remember.\n\nexport const CONFIG_PATH = '.github/site.config';\n\n// The one vendored workflow: dispatched by the release task, never by a push.\nexport const DEPLOY_WORKFLOW_FILE = 'github-pages-deploy.yml';\nexport const DEPLOY_WORKFLOW_NAME = 'Deploy to GitHub Pages';\nexport const DEPLOY_WORKFLOW_PATH = `.github/workflows/${DEPLOY_WORKFLOW_FILE}`;\n\n// Where the build step assembles the publish set, and what the workflow uploads.\nexport const SITE_DIR = '_site';\n\n// Directories that must never appear in a publish set. Two of them are the agent\n// tooling (whose skill symlinks dangle on a runner and whose content is nobody's\n// business on the public web), one is the CI plumbing, one is the dependency tree.\n// A floor, not the mechanism \u2014 the additive set is what keeps a draft or a key off\n// the site \u2014 but these are what a \"just publish everything\" instinct reaches for\n// first, so naming them fails fast with the reason attached.\nexport const NEVER_PUBLISHED = ['.claude', '.claudinite', '.github', 'node_modules'];\n\n// The three required keys, plus the one optional key. `allowEmpty` marks the value\n// whose empty form is a real, stated answer (\"no build\") rather than an omission;\n// `optional` marks the key a config may leave out entirely.\nexport const KEYS = [\n  { name: 'publish_root', allowEmpty: false },\n  { name: 'publish_paths', allowEmpty: false },\n  { name: 'build_command', allowEmpty: true },\n  { name: 'build_vars', allowEmpty: true, optional: true },\n];\n\n// A build_vars entry becomes an environment variable name, so it must be one.\n// Rejecting `FOO=bar` or `foo-bar` here means the failure lands on the config line\n// that is wrong, not as an unbound shell name three steps later.\nconst ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;\n\n// dotenv-ish: KEY=value, one per line; # comments and blank lines ignored; the value\n// may be wrapped in matching single or double quotes (so a command with trailing\n// spaces or a leading # is expressible). Returns { values, errors }.\nexport function parseConfig(text) {\n  const values = new Map();\n  const errors = [];\n  const known = new Set(KEYS.map((k) => k.name));\n\n  text.split('\\n').forEach((raw, i) => {\n    const line = raw.trim();\n    if (!line || line.startsWith('#')) return;\n    const eq = line.indexOf('=');\n    if (eq < 1) {\n      errors.push(`${CONFIG_PATH}:${i + 1}: '${line}' is not KEY=value`);\n      return;\n    }\n    const key = line.slice(0, eq).trim();\n    let value = line.slice(eq + 1).trim();\n    if (value.length >= 2 && (value[0] === '\"' || value[0] === \"'\") && value.at(-1) === value[0]) {\n      value = value.slice(1, -1);\n    }\n    if (!known.has(key)) {\n      errors.push(`${CONFIG_PATH}:${i + 1}: unknown key '${key}' \u2014 the keys are ${[...known].join(', ')}`);\n      return;\n    }\n    if (values.has(key)) errors.push(`${CONFIG_PATH}:${i + 1}: '${key}' is set twice`);\n    values.set(key, value);\n  });\n\n  for (const { name, allowEmpty, optional } of KEYS) {\n    if (!values.has(name)) {\n      if (!optional) errors.push(`${CONFIG_PATH}: required key '${name}' is missing`);\n    } else if (!allowEmpty && !values.get(name)) {\n      errors.push(`${CONFIG_PATH}: '${name}' is empty \u2014 it must name a real path`);\n    }\n  }\n\n  for (const name of (values.get('build_vars') ?? '').split(/\\s+/).filter(Boolean)) {\n    if (!ENV_NAME.test(name)) {\n      errors.push(`${CONFIG_PATH}: build_vars entry '${name}' is not a variable name \u2014 list the repo variable NAMES to export, space-separated, never their values`);\n    }\n  }\n  return { values, errors };\n}\n\n// The publish set as repo-relative paths: `root` as written, `siteRoot` as a prefix\n// (\"\" for the repo root), the paths as written, and `fullOf` mapping one to where\n// it sits in the repo.\nexport function publishSet(values) {\n  const root = values.get('publish_root') || '.';\n  const siteRoot = root === '.' ? '' : `${root.replace(/^\\.\\//, '').replace(/\\/+$/, '')}/`;\n  const paths = (values.get('publish_paths') ?? '').split(/\\s+/).filter(Boolean);\n  const fullOf = (p) => (p === '.' ? (siteRoot.replace(/\\/$/, '') || '.') : `${siteRoot}${p}`);\n  return { root, siteRoot, paths, fullOf };\n}\n\n// Has this repo adopted the standard? TWO INDEPENDENT SIGNALS, either sufficient \u2014\n// because the artifact the checks most need to catch missing IS one of them. Gating\n// on the config alone would let a repo that vendored the workflow and never wrote\n// its config pass silently, which is the one case `gp/site-config` exists to report.\nexport const adoptedPages = (ctx) => ctx.read(CONFIG_PATH) !== null || ctx.read(DEPLOY_WORKFLOW_PATH) !== null;\n",
  "packs/github-pages/pack.mjs": "import { adoptedPages, CONFIG_PATH } from 'claudinite-locator:packs/github-pages/lib.mjs';\n\n// Serving a site from GitHub Pages: the nightly release that deploys the default\n// branch, the one vendored workflow that performs the deploy, the config naming what\n// is published, and the subpath the result is served from. The version is not here:\n// public-website owns the scheme and the page stamp, and the release reaches that\n// pack's `public/version.mjs` to advance it when the pack is declared.\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'serving a site from GitHub Pages: the nightly release, the vendored deploy workflow, site.config, the serving subpath',\n    excludes: 'the version scheme and the page stamp \u2014 public-website; markup \u2014 html',\n  },\n  pitch: 'A GitHub Pages site breaks in production when a root-relative link works locally and 404s under the repo path, or when a second workflow publishes behind everyone\\'s back. This pack makes deployment a single scheduled release task that deploys the default branch, stamps the version and stops where a person must act. A couple of rules and a few checks keep the site config and the one deploy workflow honest, and the pipeline skill explains how to set it up, force a release, or roll one back.',\n  marker: CONFIG_PATH,\n  detect: adoptedPages,\n  // The release is a work item: the queue owns its trigger, its gate and its park\n  // lanes, which is the whole reason it is a task rather than a push-triggered\n  // workflow.\n  requires: ['claudinite-tasks'],\n\n  // Adoption interview. One question, a genuine fork in the road the pack cannot\n  // default: WHAT is published, an additive list only the project knows. The answer\n  // does not become config on the member's pack entry: its home is the repo's own\n  // .github/site.config, where the deploy's build step and the checks both read it.\n  questions: [\n    {\n      id: 'publish_set',\n      prompt: 'Which files and folders make up the published site \u2014 the exact list, and the directory it is rooted at? The artifact is built from this list and nothing else, so name the pages, assets and data the site actually serves (not \"everything except the tooling\").',\n      distill: \"written into the repo's own .github/site.config as publish_root + publish_paths (with build_command), which is where the deploy's build step and the gp/site-config check both read it\",\n    },\n  ],\n\n  // Settings, not repo content: no workflow, check or agent can turn these on, and a\n  // deploy that silently depends on one fails its first run for a reason nobody\n  // wrote down.\n  adoptionHandover: [\n    {\n      step: 'Settings \u2192 Pages \u2192 Build and deployment \u2192 Source = \"GitHub Actions\" (not \"Deploy from a branch\").',\n      breaks: 'actions/deploy-pages fails and nothing is ever served.',\n      done: 'the first site-release run deploys successfully.',\n    },\n    {\n      step: 'Settings \u2192 Environments \u2192 github-pages \u2192 deployment branches must allow the default branch.',\n      breaks: 'the deploy job is refused by the environment after the version is already cut.',\n      done: 'the deploy job runs rather than waiting on an environment rule.',\n    },\n  ],\n};\n",
  "packs/headless-browser/pack.mjs": "// The headless-browser pack: driving a real browser from your own process \u2014\n// resolving and pinning the build, replacing everything about the page's world\n// that would otherwise vary, and the capture mechanics. Prose only, and\n// fingerprinted by a driver reference in JS/TS source: the module specifier of a\n// browser-automation package, or a `.launch(` call site.\n\nconst DRIVER_MODULE = /['\"](playwright(?:-core)?|puppeteer(?:-core)?)['\"]/;\nconst LAUNCH_CALL = /\\b(?:chromium|firefox|webkit|puppeteer)\\.launch\\s*\\(/;\nconst SOURCE = /\\.(mjs|cjs|js|jsx|ts|tsx)$/;\n\nexport default {\n  version: '60927.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs:\n      'driving a real browser from code \u2014 resolving and pinning the build, faking the page world, capture mechanics',\n    excludes:\n      'which engine a UI golden needs and its review gate \u2014 basics writing-tests; workflow wiring \u2014 git-github',\n  },\n  pitch: 'Browser automation in a repo tends to fail in ways that look like product bugs: a driver downloading its own browser, screenshots that differ between machines, waits that guess when the page is ready. This pack gives Claude Code sessions some twenty rules for resolving the browser from the environment, serving pages from a fake origin with the network aborted by default, pinning fonts and rasterisation for stable goldens, and capturing reliably. A few checks catch network-idle waits, captures taken before fonts load, and insecure fake origins.',\n  marker: 'a browser-automation driver (playwright / puppeteer, or a .launch( call) referenced in JS/TS source',\n  detect: (ctx) =>\n    ctx.tracked.some((f) => {\n      if (!SOURCE.test(f)) return false;\n      const text = ctx.read(f);\n      return text !== null && (DRIVER_MODULE.test(text) || LAUNCH_CALL.test(text));\n    }),\n};\n",
  "packs/ios/pack.mjs": "// Technology pack: iOS app development (Xcode project, Info.plist usage strings, entitlements, signing).\nexport default {\n  version: '60925.1',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'app-target conventions for iOS \u2014 Xcode project, Info.plist usage strings, entitlements, code signing',\n    excludes: 'shipping builds to the App Store \u2014 that is app-store-release; Android equivalents are android',\n  },\n  pitch: 'An iOS repo worked on by Claude Code sessions runs into two recurring traps, and this pack names both. Its couple of rules explain that a sandbox has no macOS or Swift toolchain, so a change counts as verified only once the macOS CI runner reports on it, and that Apple\\'s developer documentation pages render in JavaScript, so sessions should read the JSON mirror instead. It is prose only, and is where the repo\\'s further lessons about Xcode, signing and devices will accumulate.',\n  marker: 'ios/Runner/Info.plist',\n  detect: (ctx) => ctx.tracked.some((f) => f.endsWith('ios/Runner/Info.plist')),\n};\n",
  "packs/jwt/pack.mjs": "// The JSON Web Token pack: minting and validating JWTs safely. It contributes\n// no prose; two action skills (jwt-minting, jwt-validation) carry the judgment\n// half, and five declared checks under them carry the static half.\n//\n// Fingerprinted by a JWT library reference in JS/TS/Python source. The marker\n// only *suspects* the pack; declaring it is the project's call, like every pack.\nconst JWT_LIB = /['\"](jsonwebtoken|express-jwt|jwks-rsa|node-jose|jose|python-jose)['\"]|^\\s*(import\\s+jwt\\b|from\\s+jwt(\\.[\\w.]*)?\\s+import\\b)/m;\nconst SOURCE = /\\.(mjs|cjs|js|jsx|ts|tsx|py)$/;\n\nexport default {\n  version: '60925.1',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'minting and validating JSON Web Tokens: algorithm pinning, claim validation, key strength and secrecy, expiry, JWE',\n    excludes: 'the Google-issuer validator config \u2014 google-identity; OAuth client-side token acquisition \u2014 chrome-extension',\n  },\n  pitch: 'Token handling is where small mistakes become security holes: accepting the none algorithm, leaving algorithms unpinned, hardcoding a signing secret, issuing tokens that never expire. This pack guards a repo that mints or validates JSON Web Tokens with a handful of checks that run on every change, blocking the critical mistakes and flagging missing audience binding or expiry. Two skills guide Claude Code sessions through minting tokens, from algorithm and key choice to claims, and wiring verification correctly. It adds no always-on prose.',\n  marker: 'a JWT library (jsonwebtoken / jose / PyJWT) referenced in JS/TS/Python source',\n  detect: (ctx) =>\n    ctx.tracked.some((f) => {\n      if (!SOURCE.test(f)) return false;\n      const text = ctx.read(f);\n      return text !== null && JWT_LIB.test(text);\n    }),\n};\n",
  "packs/leaflet/pack.mjs": "\n// Leaflet pack: portable runtime gotchas for the Leaflet web-mapping library\n// (map init, tile layers, markers/divIcons, and CDN-loaded plugins like\n// Leaflet.markercluster).\n\nconst LEAFLET_ASSET = /\\bleaflet(\\.js|\\.css|@[\\d.]|[-/]dist)/i;\nconst LEAFLET_API = /\\bL\\.(map|tileLayer|markerClusterGroup)\\s*\\(/;\nconst SOURCE = /\\.(html?|mjs|cjs|jsx?|tsx?)$/;\n\nexport default {\n  version: '60925.1',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'map rendering with the Leaflet library \u2014 map init options, tile layers, markers and divIcons, CDN plugin pinning',\n    excludes: 'generic HTML markup rules \u2014 that is html; non-map dependency policy belongs to node',\n  },\n  pitch: 'Maps built with Leaflet fail in small, visible ways: a plugin missing from the CDN takes the whole map down, an embedded map hijacks page scrolling, or the tile provider\\'s required attribution disappears. This pack gives Claude Code sessions a few rules for feature-detecting plugins with a fallback to core, disabling scroll-wheel zoom on embedded maps, keeping attribution, and transforming markers correctly. A couple of checks block CDN assets without integrity hashes and tile layers without attribution.',\n  marker: 'a Leaflet reference (CDN asset, or an L.map/L.tileLayer/L.markerClusterGroup call) in HTML/JS source',\n  detect: (ctx) =>\n    ctx.tracked.some((f) => {\n      if (!SOURCE.test(f)) return false;\n      const text = ctx.read(f);\n      return text !== null && (LEAFLET_ASSET.test(text) || LEAFLET_API.test(text));\n    }),\n};\n",
  "packs/macos/pack.mjs": "\n// Technology pack: a native macOS app \u2014 the app bundle, TCC and Hardened\n// Runtime, the Developer ID / notarization / DMG distribution lane, and the\n// process-lifecycle rules a Mac agent app has to get right.\n//\n// Fingerprint: a `Package.swift` at the repo root or one directory down (a\n// monorepo's `mac/` dir), never deeper.\nconst hasMarkerNearRoot = (ctx, marker) =>\n  ctx.tracked.some((f) => {\n    const parts = f.split('/');\n    return parts[parts.length - 1] === marker && parts.length <= 2;\n  });\n\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'native macOS apps: app-bundle assembly, TCC usage strings, Hardened Runtime entitlements, Developer ID signing, notarization and DMG distribution',\n    excludes: 'Mac App Store submission \u2014 app-store-release; iPhone app targets \u2014 ios; workflow YAML mechanics \u2014 git-github',\n  },\n  pitch: 'Shipping a native Mac app means getting the bundle, signing, Hardened Runtime and notarization right, and each mistake surfaces late. This pack gives Claude Code sessions about two dozen rules covering app bundle assembly from SwiftPM, the Developer ID to notarization to DMG lane, CI signing identities, and privacy traps such as speech recognition streaming to Apple by default. Skills cover assembling the app bundle and deciding which gate a protected resource sits behind, and a handful of checks enforce steps such as notarizing then stapling.',\n  marker: 'Package.swift (at the repo root or one directory down)',\n  detect: (ctx) => hasMarkerNearRoot(ctx, 'Package.swift'),\n};\n",
  "packs/node/pack.mjs": "\n// Conventions for a Node/npm project. Fingerprint: a package.json at the repo\n// root or one directory down, never deeper.\nconst hasMarkerNearRoot = (ctx, marker) =>\n  ctx.tracked.some((f) => {\n    const parts = f.split('/');\n    return parts[parts.length - 1] === marker && parts.length <= 2;\n  });\n\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'conventions for a Node/npm project \u2014 module resolution, ESM vs CJS, dependency justification, jsdom test divergences',\n    excludes: 'browser-runtime API behaviour \u2014 that is html or web-speech; Python packaging is python',\n  },\n  pitch: 'Keeps Claude Code sessions in a Node.js repo clear of the quiet failures that pass locally and break later. Several rules cover named imports from CommonJS packages that silently come back undefined, scripts that truncate their own output by calling process.exit, CI pinning an older Node than the sandbox, and jsdom behaving unlike a real browser. A few checks flag needless dependencies and text mangled by btoa, and the node-test-discovery skill plus a blocking check stop a test command that finds zero tests and still reports green.',\n  marker: 'package.json (at the repo root or one directory down)',\n  detect: (ctx) => hasMarkerNearRoot(ctx, 'package.json'),\n  // `dirs` is the member's own value, from the node pack entry's `config` in\n  // .claudinite-settings.json; unset means the repo root. A cloud setup script\n  // starts in the checkout's PARENT, so env.mjs runs these from the checkout\n  // and the `cd \"$d\"` is relative to it.\n  env: {\n    label: 'Node dependencies (npm ci)',\n    setup: (p) =>\n      (p.dirs?.length ? p.dirs : ['.'])\n        .map((d) => `( cd \"${d}\" && npm ci ) || true`)\n        .join('\\n'),\n    probe: (p) =>\n      (p.dirs?.length ? p.dirs : ['.'])\n        .map((d) => `[ -d \"${d}/node_modules\" ]`)\n        .join(' && '),\n  },\n};\n",
  "packs/numpy-image-processing/pack.mjs": "// numpy-image-processing pack: numeric image analysis in Python on the\n// NumPy + SciPy (`ndimage`) + scikit-image + Pillow stack - deriving a mask,\n// skeleton or threshold from an image array, and rendering the result.\n//\n// Fingerprint: `numpy` and `scipy` named together in a near-root Python\n// dependency manifest (`requirements*.txt` or `pyproject.toml`).\nconst MANIFEST = /(^|\\/)(requirements[^/]*\\.txt|pyproject\\.toml)$/;\nconst NUMPY = /\\bnumpy\\b/i;\nconst SCIPY = /\\bscipy\\b/i;\n\nexport default {\n  version: '60925.1',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs:\n      'numeric image analysis in Python \u2014 deriving a mask/skeleton/threshold from a NumPy image array with SciPy ndimage and scikit-image',\n    excludes:\n      'Python packaging conventions \u2014 that is python; iterate-on-an-algorithm methodology \u2014 that is research-project; browser canvas \u2014 that is html',\n  },\n  pitch: 'Image-processing code built on NumPy and SciPy fails in ways that still produce a plausible picture. This pack gives Claude Code sessions about ten rules for exactly those traps: statistics skewed by padding, thresholds that miss saturated pixels, off-by-one windows around a float center, affine transforms that pull rather than push, labels smeared by upscaling, and annotations drawn in a color that hides the signal. The result is fewer wrong measurements that look right and less time spent chasing them.',\n  marker: 'numpy and scipy named together in a near-root Python dependency manifest (requirements*.txt or pyproject.toml)',\n  detect: (ctx) =>\n    ctx.tracked.some((f) => {\n      const parts = f.split('/');\n      if (parts.length > 2 || !MANIFEST.test(f)) return false;\n      const text = ctx.read(f);\n      return text !== null && NUMPY.test(text) && SCIPY.test(text);\n    }),\n};\n",
  "packs/product-wiki/lib.mjs": "// The one path constant the manifest still reads from code: the human-reviewed\n// product-requirements sink, which doubles as the pack's fingerprint marker.\n// Every other path the standard hangs off \u2014 the index README, the wiki-page\n// classifier, the section/bullet/date grammar \u2014 lives as data in\n// declared-checks.json beside this file, run by the declarative engine\n// (engine/checks/helpers/pattern-rules.mjs); the wiki set itself is STRUCTURAL\n// (a README.md at depth >= 2 under product-wiki/, outside the sink and\n// sample-data/ subtrees), so nothing has to be kept in sync by hand.\nexport const SINK_README = 'product-wiki/product-requirements/README.md';\n",
  "packs/product-wiki/pack.mjs": "// Project-aspect standard pack: the self-growing product research wiki under\n// product-wiki/, isolated behind the reviewed product-requirements crossing\n// point, and fingerprinted on that sink.\nimport { SINK_README } from 'claudinite-locator:packs/product-wiki/lib.mjs';\n\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'agent-maintained market, user and competitor research wikis \u2014 cited pages, growth logs, the reviewed product-requirements sink',\n    excludes: 'how the product is built or specced \u2014 that is spec-driven-product; requirement proofs are executable-requirements',\n  },\n  pitch: 'Gives the repo a product research wiki that grows by itself: market, user and competitor findings kept as cited pages, each opening with a short list of key insights. A weekly task researches the wiki\\'s own open questions and delivers the results as an unmerged pull request for review. Over a dozen checks enforce page structure, real source links and freshness, and wall the unreviewed research off from the code. The explore-link skill folds any URL into the right page, and writing-wiki-pages sets how pages are written.',\n  marker: SINK_README,\n  detect: (ctx) => ctx.tracked.includes(SINK_README),\n  // The isolation wall (product-wiki-isolation) and the skeleton check\n  // (product-wiki-layout) are a designed pair, both declared in this pack's\n  // declared-checks.json: the wall's glob target fails closed on an empty\n  // product-wiki/ expansion, and layout owns the missing-skeleton complaint.\n  // Adoption interview: the answers frame WHICH wikis get seeded and what the\n  // competitor set is measured against, and record as intent on the entry\n  // (`answers`), never as config. Read the repo's own product brief or spec\n  // first and confirm, rather than re-asking cold.\n  questions: [\n    {\n      id: 'product',\n      prompt: \"What is the product \u2014 what does it do, and what is the core value it delivers? If the repo already carries a product brief or spec, read it and confirm rather than asking cold.\",\n      distill: 'recorded as intent on this entry (the pack takes no config); it names what the research is about and frames every seeded wiki',\n    },\n    {\n      id: 'users',\n      prompt: 'Who are the users or customers \u2014 the segments whose needs the research must track?',\n      distill: 'recorded as intent; scopes the user-research wiki and whose problems the findings answer to',\n    },\n    {\n      id: 'market',\n      prompt: 'What market or category is this in, and who are the main competitors or alternatives? This is what the competitor research is scoped against.',\n      distill: 'recorded as intent; names the competitor set the initial competitor-landscape wiki is seeded from',\n    },\n  ],\n  // The pack's scheduled task \u2014 wiki-growth, the weekly research pass \u2014 lives in\n  // this pack's `tasks/wiki-growth/`, discovered by the scheduler's filesystem\n  // scan (packs/claudinite-tasks/discover.mjs), not declared here.\n};\n",
  "packs/public-website/public/version.mjs": "// THE PUBLIC SEAM of the public-website pack: the version a public website carries,\n// and the copy of it its pages show. A hosting pack's release reaches in here to\n// advance the version as part of cutting a release \u2014 through this file and nothing\n// else in the pack \u2014 and a release that finds the file absent (the pack undeclared,\n// so not on the mount) goes out without a bump.\n//\n// Scheme: `<major>.<ymmdd>.<build>`\n//   - major  is carried over from the version already recorded \u2014 a generation\n//            statement, raised by hand and never by a release\n//   - ymmdd  is the release date: years since EPOCH_YEAR, then zero-padded UTC\n//            month and day. 2026-09-17 is 10917; 2027-01-01 is 20101.\n//   - build  is a monotonic counter: previous build + 1, so it advances even when\n//            the day (and therefore the middle part) rolls over\n//\n// THE YEAR OFFSET is what makes the middle part mean \"later\". A bare MMDD runs\n// backwards every New Year \u2014 1231 is followed by 0101 \u2014 so the one thing every\n// reader of a version assumes stopped being true once a year, and the ordering\n// rested entirely on the build counter. Counting years from a fixed epoch makes\n// it strictly increasing with no wrap to absorb: the offset simply grows, taking\n// the part to six digits in 2035, which is still numerically above 2034's five.\n//\n// `package.json` is the single source of truth. A page says where its copy goes by\n// carrying `title=\"version \u2026\"` on whatever element should show it (a footer\n// copyright, a build line); that attribute is GENERATED from the record, and the\n// `version-stamp-matches-package` check fails a tree where the two disagree. Every\n// tracked page is a candidate: the stamp is the page's own opt-in, so nothing here\n// has to know which directory is served or by whom.\n\nexport const VERSION_RECORD = 'package.json';\n\n// The stamp as authored: `title=\"version 1.10913.7\"`, anywhere on a page. Exported so\n// the generator and the drift check spell it one way.\nexport const STAMP = /title=\"version [^\"]*\"/g;\n\n// Year zero of the scheme: 2026 is the offset's 1, so the middle part never carries\n// a leading zero and never repeats. Moving it would renumber every release ever cut,\n// so it is a constant rather than a setting.\nexport const EPOCH_YEAR = 2025;\n\nexport const isPage = (path) => path.endsWith('.html');\n\n// The date half of the version, for `now`: `<years since EPOCH_YEAR><MM><DD>`, all\n// read in UTC because a runner's local zone is not the repo's and a version must not\n// depend on which region the job landed in.\nexport function releaseDate(now = new Date()) {\n  return `${now.getUTCFullYear() - EPOCH_YEAR}${now.toISOString().slice(5, 10).replace('-', '')}`;\n}\n\n// The version that follows `current`, released at `now`. An unparseable build\n// (the initial \"1.0.0\", a hand-typed string) counts as 0, so the first bump lands\n// on 1 rather than NaN.\nexport function nextVersion(current, now = new Date()) {\n  const [major, , build] = String(current ?? '').split('.');\n  const prevBuild = Number.parseInt(build, 10);\n  return `${/^\\d+$/.test(major ?? '') ? major : '1'}.${releaseDate(now)}.${(Number.isFinite(prevBuild) ? prevBuild : 0) + 1}`;\n}\n\n// One page's stamp. A page carrying no `title=\"version \u2026\"` is returned unchanged \u2014\n// it has not asked for the version, and nothing is inserted into markup here.\nexport function stampHtml(html, version) {\n  return html.replace(STAMP, `title=\"version ${version}\"`);\n}\n\n// The bump as file contents \u2014 `{ version, files: { path: content } }` \u2014 pure over\n// `read`, so a release building a commit from a branch tip and the CLI writing a\n// working tree share one definition. `stampOnly` re-stamps from the version already\n// recorded and rewrites no record. Returns null when the tree carries no version to\n// work from; whether that parks a release or is a plain \"nothing to bump\" is the\n// caller's to say.\nexport function bumpedFiles({ read, tracked, now = new Date(), stampOnly = false }) {\n  const recordText = read(VERSION_RECORD);\n  if (recordText == null) return null;\n  const record = JSON.parse(recordText);\n  const version = stampOnly ? record.version : nextVersion(record.version, now);\n  if (!version) return null;\n  const files = {};\n  if (!stampOnly) files[VERSION_RECORD] = `${JSON.stringify({ ...record, version }, null, 2)}\\n`;\n  for (const page of tracked.filter(isPage)) {\n    const html = read(page);\n    if (html == null) continue;\n    const stamped = stampHtml(html, version);\n    if (stamped !== html) files[page] = stamped;\n  }\n  return { version, files };\n}\n",
  "packs/public-website/pack.mjs": "import { isPage, STAMP } from 'claudinite-locator:packs/public-website/public/version.mjs';\n\n// Being a public website, whatever serves it: the version the site carries and the\n// stamp its pages show, and the ways a page that fetches its own data goes quietly\n// stale. A hosting pack's release reaches `public/version.mjs` to advance the version\n// as part of cutting a release, and goes out without a bump when the file is absent.\nconst carriesAStamp = (ctx) => ctx.tracked.some((f) => isPage(f) && new RegExp(STAMP.source).test(ctx.read(f) ?? ''));\n\nexport default {\n  version: '60925.1',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'being a public website whatever serves it: the version scheme and page stamp, client-side caching and data freshness',\n    excludes: 'how the site is built, served or released \u2014 the hosting pack declared beside this one; markup \u2014 html',\n  },\n  pitch: 'For a repo that publishes a public site, this pack keeps the version shown on the pages honest and stops pages that fetch their own data from going quietly stale. The version is generated from one source and stamped into every page, and a blocking check fails any page naming a build that was never served. A handful of rules steer Claude Code sessions toward hash-based cache manifests, halves of a split payload that stay in sync, and missing data traced through to what the page actually renders.',\n  marker: 'a tracked page carrying a `title=\"version \u2026\"` stamp',\n  detect: carriesAStamp,\n  requires: ['html'],\n};\n",
  "packs/python/pack.mjs": "// Technology pack: Python packaging around an optional heavy/native dependency.\n// Fingerprint: a `pyproject.toml` at the repo root OR one directory down (a\n// subproject/tool dir), never deeper, so a pyproject.toml inside a nested\n// fixture/example/vendored tree can't trip detection. (`setup.py`/`setup.cfg`\n// are the older equivalent markers; add them here if a consumer predates\n// pyproject.toml.)\nconst hasMarkerNearRoot = (ctx, marker) =>\n  ctx.tracked.some((f) => {\n    const parts = f.split('/');\n    return parts[parts.length - 1] === marker && parts.length <= 2;\n  });\n\nexport default {\n  version: '60925.2',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'packaging and import conventions for a Python project \u2014 pyproject extras, lazy optional heavy deps, stdlib-only core',\n    excludes: 'npm and module packaging \u2014 that is node; research methodology is research-project',\n  },\n  pitch: 'For a Python package built around an optional heavy or native dependency, this pack keeps the package importable and useful without it. The python-optional-deps skill shows Claude Code sessions how to put that dependency behind a lazy, guarded import with a clear install hint, and a couple of checks enforce it: a blocking one catches a top-level import of an optional package, and an advisory one flags a missing install hint. A few rules also favour shipping a standard-library fallback behind the same interface.',\n  marker: 'pyproject.toml (at the repo root or one directory down)',\n  detect: (ctx) => hasMarkerNearRoot(ctx, 'pyproject.toml'),\n};\n",
  "packs/web-speech/pack.mjs": "// The browser voice-I/O pack: speech-to-text (webkitSpeechRecognition / the Web\n// Speech SpeechRecognition API) and text-to-speech (chrome.tts / speechSynthesis)\n// runtime gotchas that apply whenever an app reads or listens through the browser.\n// Mostly prose, with the call-site contracts in worldRules/, the web-speech-io\n// skill's rules and the voice-cache declaration beside this file as checks.\n// Fingerprinted by an actual speech-API reference in JS/TS source.\nconst SPEECH_API =\n  /\\b(webkitSpeechRecognition|SpeechRecognition|SpeechRecognitionPhrase|speechSynthesis|SpeechSynthesisUtterance|chrome\\.tts)\\b/;\nconst SOURCE = /\\.(mjs|cjs|js|jsx|ts|tsx)$/;\n\nexport default {\n  version: '60925.1',\n  minEngineVersion: '60925.1',\n  ruleRoutingGuidance: {\n    belongs: 'browser voice I/O gotchas \u2014 SpeechRecognition results and errors, speechSynthesis and chrome.tts, mic permission and lifecycle',\n    excludes: 'general MV3 service-worker and content-script mechanics \u2014 that is chrome-extension; page markup is html',\n  },\n  pitch: 'Browser speech recognition and text-to-speech are full of undocumented behaviour, and this pack keeps Claude Code sessions ahead of it. Some fifteen rules cover microphones left open, listen cycles that settle twice, an empty voice list that only means not ready yet, recognition audio streamed to the cloud, and speak calls that never resolve. Several checks read the actual call sites and block those mistakes at every commit, and the web-speech-io skill guides wiring voice input and output, including in browser extensions.',\n  marker: 'a browser speech API (SpeechRecognition / speechSynthesis / chrome.tts) referenced in JS/TS source',\n  detect: (ctx) =>\n    ctx.tracked.some((f) => {\n      if (!SOURCE.test(f)) return false;\n      const text = ctx.read(f);\n      return text !== null && SPEECH_API.test(text);\n    }),\n};\n"
};

const asDataUrl = (source) => `data:text/javascript;charset=utf-8,${encodeURIComponent(source)}`;

// `toUrl` turns a linked module's source into an importable URL; a data: URL works in
// Node and in a browser without a content-security policy forbidding it.
export async function loadLocators({ toUrl = asDataUrl } = {}) {
  const urls = {};
  const loaded = {};
  for (const [key, source] of Object.entries(SOURCES)) {
    const linked = source.replace(/(['"])claudinite-locator:([^'"]+)\1/g, (whole, quote, dep) => JSON.stringify(urls[dep]));
    urls[key] = toUrl(linked);
    loaded[key] = await import(urls[key]);
  }
  return new Map(PACKS.filter((p) => p.locator).map((p) => [p.id, loaded[p.locator].default.detect]));
}
